WITH remaining_keys AS (SELECT page, event_type FROM web_events INTERSECT SELECT page, event_type FROM web_events WHERE TO_DATE(event_time) >= '2024-02-01'), verified AS (SELECT s.* FROM web_events s INNER JOIN remaining_keys k ON s.page = k.page AND s.event_type = k.event_type) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, (SELECT MIN(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS min_web_event_duration_sec FROM verified s;
